// Données factices, pour tester le message sans provoquer de vraie panne
return [{ json: {
  workflow: { name: 'Exemple (test)' },
  execution: { lastNodeExecuted: 'Lire NVD (critiques)', mode: 'trigger',
               error: { message: 'Ceci est un test : tout va bien.' } },
} }];

// Construit le message d'alerte à partir des infos fournies par l'Error Trigger
const d = $input.first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ex = d.execution ?? {};
const err = ex.error ?? d.trigger?.error ?? {};
const texte = [
  `🚨 <b>Panne : ${esc(d.workflow?.name ?? 'workflow inconnu')}</b>`,
  '',
  `<b>Bloc :</b> ${esc(ex.lastNodeExecuted ?? '?')}`,
  `<b>Erreur :</b> ${esc(String(err.message ?? 'inconnue').slice(0, 300))}`,
  `<b>Mode :</b> ${esc(ex.mode ?? '?')}`,
  ex.url ? `\n<a href="${esc(ex.url)}">Voir l'exécution dans n8n</a>` : '',
].join('\n');
return [{ json: { texte } }];
